/// <summary>
/// The response of the inbound sales order API.
/// </summary>
[DataContractAttribute]
public class DYLO_SalesOrderApiResponseContract
{
    str                     status;
    boolean                 success;
    SalesId                 salesId;
    DYLO_CorrelationId      correlationId;
    DYLO_ExternalOrderRef   externalOrderId;
    boolean                 duplicate;
    DYLO_ApiErrorCode       errorCode;
    str                     message;
    List                    errors;

    public const str StatusSuccess = 'Success';
    public const str StatusFailed  = 'Failed';
}

Method.Source:
public void new()
{
    errors = new List(Types::String);
    status = DYLO_SalesOrderApiResponseContract::StatusFailed;
}

public static DYLO_SalesOrderApiResponseContract construct()
{
    return new DYLO_SalesOrderApiResponseContract();
}

/// <summary>
/// Creates a response that echoes the identifiers of a request.
/// </summary>
public static DYLO_SalesOrderApiResponseContract newFromRequest(DYLO_SalesOrderApiRequestContract _request)
{
    DYLO_SalesOrderApiResponseContract response = DYLO_SalesOrderApiResponseContract::construct();

    if (_request)
    {
        response.parmCorrelationId(_request.parmCorrelationId());
        response.parmExternalOrderId(_request.parmExternalOrderId());
    }

    return response;
}

[DataMemberAttribute('status')]
public str parmStatus(str _status = status)
{
    status = _status;
    return status;
}

[DataMemberAttribute('success')]
public boolean parmSuccess(boolean _success = success)
{
    success = _success;
    return success;
}

[DataMemberAttribute('salesId')]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

[DataMemberAttribute('correlationId')]
public DYLO_CorrelationId parmCorrelationId(DYLO_CorrelationId _correlationId = correlationId)
{
    correlationId = _correlationId;
    return correlationId;
}

[DataMemberAttribute('externalOrderId')]
public DYLO_ExternalOrderRef parmExternalOrderId(DYLO_ExternalOrderRef _externalOrderId = externalOrderId)
{
    externalOrderId = _externalOrderId;
    return externalOrderId;
}

[DataMemberAttribute('duplicate')]
public boolean parmDuplicate(boolean _duplicate = duplicate)
{
    duplicate = _duplicate;
    return duplicate;
}

[DataMemberAttribute('errorCode')]
public DYLO_ApiErrorCode parmErrorCode(DYLO_ApiErrorCode _errorCode = errorCode)
{
    errorCode = _errorCode;
    return errorCode;
}

[DataMemberAttribute('message')]
public str parmMessage(str _message = message)
{
    message = _message;
    return message;
}

[
    DataMemberAttribute('errors'),
    AifCollectionTypeAttribute('_errors', Types::String),
    AifCollectionTypeAttribute('return', Types::String),
    DataCollectionAttribute(Types::String)
]
public List parmErrors(List _errors = errors)
{
    errors = _errors;
    return errors;
}

/// <summary>
/// Adds an error; the first error added gives the error code.
/// </summary>
public void addError(DYLO_ApiErrorCode _errorCode, str _message)
{
    if (!errorCode)
    {
        errorCode = _errorCode;
    }

    if (!errors)
    {
        errors = new List(Types::String);
    }

    errors.addEnd(_message);
}

/// <summary>
/// Marks the response as failed and joins all error messages into the message.
/// </summary>
public void setFailed()
{
    ListEnumerator  enumerator;
    str             joined;

    status    = DYLO_SalesOrderApiResponseContract::StatusFailed;
    success   = false;
    salesId   = '';
    duplicate = false;

    if (errors)
    {
        enumerator = errors.getEnumerator();
        while (enumerator.moveNext())
        {
            joined += (joined ? ' ' : '') + enumerator.current();
        }
    }

    message = joined;
}

/// <summary>
/// Marks the response as successful.
/// </summary>
public void setSuccess(SalesId _salesId, boolean _duplicate)
{
    status    = DYLO_SalesOrderApiResponseContract::StatusSuccess;
    success   = true;
    salesId   = _salesId;
    duplicate = _duplicate;
    errorCode = '';
    message   = '';
    errors    = new List(Types::String);
}
